# YT Auto GPU worker for Kaggle (generated by kaggle_launch.py; do not edit the copy on Kaggle).
# Runs as a "Save & Run" batch session on GPU T4 x2 with Internet on. Pull model: it only makes OUTBOUND requests to
# your app (/worker API) or your n8n GPU Bridge, renders clips, uploads them, and exits when the queue is empty.
# No tunnel, no server, no inbound traffic.
import base64, io, json, os, subprocess, sys, tarfile, time

CONFIG = json.loads(base64.b64decode("__CONFIG_B64__").decode())
PAYLOAD = "__PAYLOAD_B64__"


def log(*a): print("[kernel]", *a, flush=True)


def secret(name):
    """Prefer a Kaggle Secret (Add-ons -> Secrets) over the value embedded in this private notebook."""
    try:
        from kaggle_secrets import UserSecretsClient
        v = UserSecretsClient().get_secret(name)
        if v: return v
    except Exception:
        pass
    return CONFIG.get("token", "")


def free_ram_gb():
    try:
        for line in open("/proc/meminfo"):
            if line.startswith("MemAvailable:"): return int(line.split()[1]) / 1e6
    except Exception:
        pass
    return 0.0


def main():
    t_start = time.time()
    os.environ.setdefault("HF_HOME", "/tmp/hf")
    os.environ.update({k: str(v) for k, v in (CONFIG.get("env") or {}).items()})   # HY15_* / WAN_* / LTX_* knobs
    root = CONFIG.get("workdir") or ("/kaggle/working/yta" if os.path.isdir("/kaggle") else "/tmp/yta_kernel")
    os.makedirs(root, exist_ok=True)
    tarfile.open(fileobj=io.BytesIO(base64.b64decode(PAYLOAD)), mode="r:gz").extractall(root)
    sim = CONFIG.get("simulate", False)
    if not sim:
        log("installing python packages")
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-U", "diffusers>=0.33", "transformers", "accelerate",
                        "sentencepiece", "imageio", "imageio-ffmpeg", "ftfy", "requests", "protobuf", "bitsandbytes>=0.45", "pillow", "numpy"], check=False)
        subprocess.run(["nvidia-smi"], check=False)
        try:
            import torch; gpus = torch.cuda.device_count()
        except Exception:
            gpus = 0
    else:
        gpus = int(CONFIG.get("gpus", 2))
    if gpus == 0 and not sim:
        log("no GPU in this session (accelerator not granted?) -> exiting so the router falls back"); sys.exit(3)
    if CONFIG["mode"] == "selftest":
        # one 9:16 test clip, no server needed: proves the GPU, the install and the model work; ~10-25 min incl. download
        sys.path.insert(0, root); os.environ.setdefault("CUDA_VISIBLE_DEVICES", "0")
        outdir = "/kaggle/working" if os.path.isdir("/kaggle/working") else root
        c = {"id": "selftest", "idx": 0, "width": 480, "height": 832, "seconds": 3,
             "prompt": CONFIG.get("prompt") or "A golden coin spinning slowly on a dark wooden desk, soft rim light, shallow depth of field, cinematic"}
        out = os.path.join(outdir, "test_clip_9x16.mp4"); t0 = time.time()
        if sim:
            from worker import mock_clip; mock_clip(c, out); model = "mock"
        else:
            import t4_models; model = CONFIG.get("video_model", "wan21-diffusers")
            if model == "hy15-i2v":   # image-to-video selftest needs a first frame: a plain warm gradient (no download)
                from PIL import Image
                import numpy as np
                y = np.linspace(0, 1, 832)[:, None, None]; x = np.linspace(0, 1, 480)[None, :, None]
                arr = (np.concatenate([0.9 - 0.4 * y + 0 * x, 0.6 - 0.3 * y + 0.1 * x, 0.2 + 0.2 * x + 0 * y], 2) * 255).astype("uint8")
                buf = io.BytesIO(); Image.fromarray(arr).save(buf, "JPEG", quality=90)
                c["image_b64"] = base64.b64encode(buf.getvalue()).decode()
            gen = t4_models.T2V[model](); t_load = time.time() - t0; gen(c, out)
        info = {"model": model, "gpus": gpus, "seconds_total": round(time.time() - t0, 1), "file": os.path.basename(out),
                "bytes": os.path.getsize(out)}
        json.dump(info, open(os.path.join(outdir, "test_clip_info.json"), "w")); log("SELFTEST OK", info); return
    max_min = float(CONFIG.get("max_hours", 11.0)) * 60 - (time.time() - t_start) / 60
    parallel = max(1, min(gpus or 1, int(CONFIG.get("parallel", 2))))
    tok = secret("YTA_WORKER_TOKEN" if CONFIG["mode"] == "app" else "GPU_BRIDGE_TOKEN")
    py = sys.executable
    procs = []
    for i in range(parallel):
        if i > 0 and not sim:
            # each process keeps its own text encoder (~10 GB) in system RAM; start GPU 2 only if it fits in Kaggle's ~29 GB
            wait_until = time.time() + 60 * float(CONFIG.get("second_gpu_delay_min", 12))
            while time.time() < wait_until and procs[0].poll() is None: time.sleep(20)
            if procs[0].poll() is not None: log("GPU 0 worker already finished; queue empty"); break
            if free_ram_gb() < float(CONFIG.get("min_free_ram_gb", 14)):
                log(f"only {free_ram_gb():.1f} GB RAM free -> staying on one GPU"); break
        env = dict(os.environ, CUDA_VISIBLE_DEVICES=str(i), ONE_MODEL="1", PYTHONUNBUFFERED="1",
                   HF_HOME=os.environ.get("HF_HOME", "/tmp/hf"))   # HunyuanVideo-1.5 weights are ~35 GB: keep them out of /kaggle/working (20 GB)
        name = f"kaggle-gpu{i}"
        if CONFIG["mode"] == "app":
            cmd = [py, os.path.join(root, "worker.py"), "--server", CONFIG["server"], "--token", tok, "--once",
                   "--name", name, "--batch", "2", "--deadline-min", f"{max_min:.0f}"]
            if sim: cmd += ["--mock"]
            else: cmd += ["--video-model", CONFIG.get("video_model", "wan21-diffusers"), "--i2v-model", CONFIG.get("i2v_model", "ltx"),
                          "--image-model", CONFIG.get("image_model", "flux-schnell"), "--avatar-model", CONFIG.get("avatar_model", "fallback")]
        else:
            cmd = [py, os.path.join(root, "yta_gpu_worker.py"), "--bridge", CONFIG["bridge"], "--token", tok,
                   "--name", name, "--deadline-min", f"{max_min:.0f}", "--backend", "mock" if sim else "gpu",
                   "--model", CONFIG.get("video_model", "wan21-diffusers")]
        log("starting", name)
        procs.append(subprocess.Popen(cmd, env=env, cwd=root))
    hard_stop = t_start + float(CONFIG.get("max_hours", 11.0)) * 3600 + 900
    while any(p.poll() is None for p in procs):
        if time.time() > hard_stop:
            log("hard stop: killing workers (claimed clips are re-queued by the server after 30 min)")
            for p in procs: p.kill()
            break
        time.sleep(15)
    log("done in", round((time.time() - t_start) / 60, 1), "min; exit codes", [p.returncode for p in procs])


if __name__ == "__main__": main()
